find:
if (leaving.current) return false;
if (replacementPending.current) return true;
if (!draft.current!.dirty) return false;
try {
  return !(await save());
} catch (error) {
  await action.run(async () => {
    throw error;
  });
  return true;
}

replace:
if (leaving.current) return false;
if (replacementPending.current) return true;
if (!draft.current!.dirty) return false;
try {
  void save(); return false;
} catch (error) {
  await action.run(async () => {
    throw error;
  });
  return true;
}
